import{syncProcessMovie}from './process-player.js?v=20261023-physicscomplete01';
import{tasksForPhy1,validPhy1,advancePhy1,numericPhy1,experimentOptions,experimentResult,experimentCases,experimentValid}from './phy1-models.js?v=20261023-physicscomplete01';import{showPhy1}from './phy1-visuals.js?v=20261023-physicscomplete01';export{showPhy1};
export function mountPhy1(l,p,root,{save,done,feedback}){let ts=tasksForPhy1(l.widget.slice(5)),w=p.widget;w.phy1Task??=ts[0].id;w.phy1Drafts??={};w.phy1Passed??=[];let i=ts.findIndex(t=>t.id===w.phy1Task);if(i<0)i=0;let t=ts[i],v=w.phy1Drafts[t.id]??={case:0,answer:'',seen:[],step:0},$=s=>root.querySelector(s),remount=()=>mountPhy1(l,p,root,{save,done,feedback});p.widgetDone=ts.every(t=>w.phy1Passed.includes(t.id));
syncProcessMovie(l,1,{process:false});
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([a,b])=>`<option value="${a}" ${String(a)===String(value)?'selected':''}>${b}</option>`).join('')}</select>`;
let body='',draw,valid;
if(t.type==='compare'){let c=t.cases[v.case];body=field('phy1Case','Scenario',t.cases.map((c,j)=>[j,c[1]]),v.case)+field('phy1Answer','Predict and explain',c[2].map((s,j)=>[j,s]),v.answer)+'<button class="secondary" id="revealPhy1">Reveal evidence →</button><p id="phy1Readout" aria-live="polite"></p>';draw=()=>{let r=v.revealed===v.case;showPhy1(t.kind,{state:c[0],title:t.title,label:c[1],concealed:!r,progress:r?1:0,step:r?5:0});$('#phy1Readout').textContent=r?c[4]:'Predict, then reveal and record.';};valid=()=>v.revealed===v.case&&validPhy1(c,v.answer);}
else if(t.type==='sequence'){body=field('phy1Next','Next stage',t.route.map((id,j)=>[id,t.labels[j]]),v.next)+'<button class="secondary" id="advancePhy1">Advance pathway →</button><p id="phy1Readout" aria-live="polite"></p>';draw=()=>{showPhy1(t.kind,{title:t.title,progress:v.step/t.route.length,step:v.step,label:v.step+' / '+t.route.length+' stages'});$('#phy1Readout').textContent=v.step?t.labels.slice(0,v.step).join(' → '):'Select the first stage.';};valid=()=>v.step===t.route.length;}

else if(t.type==='experiment'){let o=experimentOptions[t.experiment];v.a??=o.a[0][0];v.b??=o.b[0][0];v.observed??=[];body=field('phy1A',o.labels[0],o.a,v.a)+field('phy1B',o.labels[1],o.b,v.b)+'<label class="field-label">Predict / '+o.unit+'<input class="lab-input" type="number" step="any" id="phy1Prediction" value="'+(v.prediction??'')+'"></label><button class="secondary" id="phy1Run">Reveal model output →</button><p id="phy1Output"></p>'+field('phy1Interpretation','Conclusion',[['limited','A bounded illustrative comparison; evaluate omitted effects'],['universal','This output proves the best decision for every real system']],v.interpretation);draw=()=>{let r=experimentResult(t.experiment,v.a,v.b);showPhy1(t.kind,{a:v.a,b:v.b,revealed:v.ran,title:t.title});$('#phy1Output').textContent=(t.experiment==='stores'?'Target: '+r.target+' store. ':'')+(v.ran?'Model output: '+Number(r.value.toFixed(3))+' '+o.unit:'Predict first. Use the given equation or energy account.');};valid=()=>!!v.ran&&numericPhy1(v.prediction,experimentResult(t.experiment,v.a,v.b).value);}
else{body='<p>'+t.prompt+'</p><label class="field-label" for="phy1Number">Your result / '+(t.unit||'supplied units')+'</label><input class="lab-input" id="phy1Number" type="number" step="any" value="'+(v.number??'')+'">'+field('phy1Reason','Reasoning',t.reasonChoices.map((s,j)=>[j,s]),v.reason);draw=()=>showPhy1(t.kind,{title:t.title,label:'Original illustrative evidence'});valid=()=>numericPhy1(v.number,t.answer)&&v.reason!==''&&v.reason!==undefined&&Number(v.reason)===t.reason;}
root.innerHTML='<p class="activity-count">'+(i+1)+' / '+ts.length+' · '+t.title+'</p>'+body+'<p id="phy1Evidence"></p><div class="lab-actions"><button class="secondary" id="recordPhy1">Record reasoning</button><button class="secondary" id="nextPhy1">Next challenge →</button></div><p id="phy1Progress"></p>';
const status=()=>{$('#phy1Evidence').textContent=t.type==='compare'?t.cases.map((c,j)=>(v.seen.includes(j)?'✓ ':'○ ')+c[1]).join(' · '):t.type==='experiment'?'Recorded settings: '+v.observed.join('; '):w.phy1Passed.includes(t.id)?'Challenge recorded.':'';$('#phy1Progress').textContent=ts.filter(t=>w.phy1Passed.includes(t.id)).length+' / '+ts.length+' complete';};draw();status();
for(let el of root.querySelectorAll('select,input')){el.onchange=e=>{let id=e.target.id,val=e.target.value;if(id==='phy1A'||id==='phy1B'){if(!val)return;v[id==='phy1A'?'a':'b']=val;v.ran=false;v.prediction='';save();remount();return;}if(id==='phy1Interpretation'){v.interpretation=val;save();return;}if(id==='phy1Prediction'){v.prediction=val;save();return;}if(id==='phy1Case'){if(val==='')return;v.case=Number(val);v.answer='';delete v.revealed;save();remount();return;}if(id==='phy1Answer')v.answer=val;else if(id==='phy1Next')v.next=val;else if(id==='phy1Number')v.number=val;else if(id==='phy1Reason')v.reason=val;save();};if(el.tagName==='INPUT')el.oninput=e=>{v[e.target.id==='phy1Prediction'?'prediction':'number']=e.target.value;save();};}
if($('#phy1Run'))$('#phy1Run').onclick=()=>{if(v.prediction===''||v.prediction===undefined){feedback('Predict a number first.',true);return;}v.ran=true;save();draw();};
if($('#revealPhy1'))$('#revealPhy1').onclick=()=>{if(v.answer===''){feedback('Choose a prediction first.',true);return;}v.revealed=v.case;save();draw();feedback(validPhy1(t.cases[v.case],v.answer)?'Prediction agrees. Record the evidence.':t.cases[v.case][4],!validPhy1(t.cases[v.case],v.answer));};
if($('#advancePhy1'))$('#advancePhy1').onclick=()=>{let n=advancePhy1(t.route,v.step,v.next);if(n===v.step){feedback(t.why+' Choose the next stage in order.',true);return;}v.step=n;v.next='';save();remount();};
$('#recordPhy1').onclick=()=>{if(!valid()){feedback((t.type==='compare'?t.cases[v.case][4]:t.why)+' Check your evidence and reasoning.',true);return;}if(t.type==='compare'&&!v.seen.includes(v.case))v.seen.push(v.case);if(t.type==='experiment'){let key=v.a+':'+v.b;if(!v.observed.includes(key))v.observed.push(key);}let finished=t.type==='experiment'?experimentValid(t.experiment,v):t.type!=='compare'||v.seen.length===t.cases.length;if(finished&&!w.phy1Passed.includes(t.id))w.phy1Passed.push(t.id);p.widgetDone=ts.every(t=>w.phy1Passed.includes(t.id));if(p.widgetDone)done();save();status();feedback(finished?'Challenge recorded.':t.type==='experiment'&&experimentCases(t.experiment).every(k=>v.observed.includes(k))?'All required settings recorded. Choose a conclusion that respects the model limits.':'Recorded. Compare the remaining scenarios.');};$('#nextPhy1').onclick=()=>{if(!w.phy1Passed.includes(t.id)){feedback('Complete this challenge first.',true);return;}w.phy1Task=ts[(i+1)%ts.length].id;save();remount();};}
